<?php
/** TEMP PS S1676 run e — cart-abandoned-1/2.php DEPLOY (Raimio tekstai), backup, DB draft sync, peržiūros į terra@. */
add_action('init', function(){
  if (!isset($_GET['ps_s1676e'])) return; global $wpdb; $p=$wpdb->prefix; $o=array('v'=>'S1676 e');
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $dir=PETSHOP_CORE_DIR.'templates/emails/'; $bk=wp_upload_dir()['basedir'].'/ps-backups/';
  $F=array('cart-abandoned-1.php'=>array('','f31df8f7d1762b166a52565f04aae9a0','f8bd8dc86046f0c7c89c26802e5d790c'),'cart-abandoned-2.php'=>array('','8c203239f3196efab9bc40be96a43175','fe362694f28c4c64e4bb2e0d4266b799'));
  foreach($F as $n=>$x){ $f=$dir.$n; $r=array();
    $r['senas_md5']=md5_file($f); if($r['senas_md5']!==$x[1]){ $r['STOP']='senas md5 nesutampa'; $o[$n]=$r; continue; }
    $kodas=base64_decode($x[0]); if(md5($kodas)!==$x[2]){ $r['STOP']='b64 md5'; $o[$n]=$r; continue; }
    if(@token_get_all($kodas,TOKEN_PARSE)===false){ $r['STOP']='SINTAKSE'; $o[$n]=$r; continue; }
    if(!copy($f,$bk.$n.'.bak_s1676')){ $r['STOP']='backup'; $o[$n]=$r; continue; }
    file_put_contents($f,$kodas); $r['naujas_md5']=md5_file($f); $r['ok']=($r['naujas_md5']===$x[2]); $r['bak']=$bk.$n.'.bak_s1676'; $o[$n]=$r; }
  // DB draft sync (id 54/55), kad perziura rodytu ta pati
  $T=Petshop_Laiskai_Turinys::lentele();
  foreach(array(54=>array('cart_abandoned','Krepšelyje liko jūsų prekės','Sveiki, jūsų krepšelis išsaugotas. Jei norėsite tęsti, prekių ieškoti iš naujo nereikės.'),55=>array('cart_abandoned_2','Jūsų krepšelis dar laukia','Sveiki, jūsų pasirinktos prekės vis dar krepšelyje. Jei kyla klausimų ar norite pasitarti dėl pasirinkimo, atsakykite į šį laišką — padėsime.')) as $id=>$x){
    $row=$wpdb->get_row($wpdb->prepare("SELECT flow,status,blocks_json,notes FROM `$T` WHERE id=%d",$id),ARRAY_A);
    if(!$row||$row['flow']!==$x[0]||$row['status']!=='draft'){ $o['db'][$id]='PRALEISTA'; continue; }
    $bl=json_decode($row['blocks_json'],true); $bl[0]['text']=$x[2];
    $o['db'][$id]=$wpdb->update($T,array('subject'=>$x[1],'blocks_json'=>wp_json_encode($bl),'notes'=>$row['notes'].' · S1676: tekstas pagal Raimį (sinchronizuota su kodo šablonu)'),array('id'=>$id));
  }
  // perziuros is KODO sablono su naujais failais
  $it2=array(array('name'=>'Josera Help Sensitive 12,5 kg','quantity'=>1),array('name'=>'CHURU vištienos skanėstas 4 vnt.','quantity'=>2));
  foreach(array('cart_abandoned'=>$it2,'cart_abandoned_1preke'=>array($it2[0]),'cart_abandoned_2'=>$it2) as $k=>$items){
    $flow=($k==='cart_abandoned_1preke')?'cart_abandoned':$k;
    $rf=Petshop_Email_Dispatch::render($flow,array('cart_items'=>$items,'recovery_url'=>'https://petshop.lt/krepselis/'),array('flow_class'=>'marketing','recipient_email'=>'pavyzdys@petshop.lt'));
    $ok=!empty($rf['html'])?wp_mail('terra@petshop.lt','[PERŽIŪRA S1676 v2] '.$k.' — '.$rf['subject'],$rf['html'],array('Content-Type: text/html; charset=UTF-8')):false;
    $o['perziura'][$k]=array('subj'=>$rf['subject'],'ok'=>$ok,'istrauka'=>mb_substr(trim(preg_replace('/\s+/',' ',strip_tags($rf['html']))),0,260));
  }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT); exit;
});
